use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::task::JoinHandle;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvictReason {
    Expired,
    Lru,
    Memory,
}

pub trait EstimateSize {
    fn estimated_size(&self) -> usize;
}

impl EstimateSize for String {
    fn estimated_size(&self) -> usize {
        self.len() * 2
    }
}
impl EstimateSize for &str {
    fn estimated_size(&self) -> usize {
        self.len() * 2
    }
}
impl EstimateSize for i64 {
    fn estimated_size(&self) -> usize {
        8
    }
}
impl EstimateSize for u64 {
    fn estimated_size(&self) -> usize {
        8
    }
}
impl EstimateSize for bool {
    fn estimated_size(&self) -> usize {
        4
    }
}

struct Entry<V> {
    value: Arc<V>,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

pub type OnEvictFn = Arc<dyn Fn(&str, EvictReason) + Send + Sync>;

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<OnEvictFn>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_millis(60_000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5000),
            on_evict: None,
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Stats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct Inner<V> {
    entries: HashMap<Arc<str>, Entry<V>>,
    /// front (idx 0) = MRU, last = LRU
    access_order: Vec<Arc<str>>,
    current_memory: usize,
    hits: u64,
    misses: u64,
    evictions: u64,
    expirations: u64,
    config: CacheConfig,
}

impl<V> Inner<V> {
    fn move_to_front(&mut self, key: &str) {
        if let Some(pos) = self.access_order.iter().position(|k| &**k == key) {
            let k = self.access_order.remove(pos);
            self.access_order.insert(0, k);
        }
    }

    fn delete(&mut self, key: &str, reason: EvictReason) -> bool {
        let Some(entry) = self.entries.remove(key) else {
            return false;
        };
        self.current_memory = self.current_memory.saturating_sub(entry.size);
        self.access_order.retain(|k| &**k != key);
        match reason {
            EvictReason::Expired => self.expirations += 1,
            _ => self.evictions += 1,
        }
        if let Some(cb) = self.config.on_evict.as_ref() {
            cb(key, reason);
        }
        true
    }

    fn evict_lru(&mut self, reason: EvictReason) {
        if let Some(key_arc) = self.access_order.pop() {
            if let Some(entry) = self.entries.remove(&*key_arc) {
                self.current_memory = self.current_memory.saturating_sub(entry.size);
                match reason {
                    EvictReason::Expired => self.expirations += 1,
                    _ => self.evictions += 1,
                }
                if let Some(cb) = self.config.on_evict.as_ref() {
                    cb(&key_arc, reason);
                }
            }
        }
    }

    fn evict_expired(&mut self) {
        let now = Instant::now();
        let expired: Vec<Arc<str>> = self
            .entries
            .iter()
            .filter(|(_, e)| now > e.expires_at)
            .map(|(k, _)| Arc::clone(k))
            .collect();
        for k in expired {
            self.delete(&k, EvictReason::Expired);
        }
    }
}

pub struct LRUCache<V> {
    inner: Arc<Mutex<Inner<V>>>,
    eviction_task: Mutex<Option<JoinHandle<()>>>,
}

impl<V: Send + Sync + 'static> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(Mutex::new(Inner {
                entries: HashMap::new(),
                access_order: Vec::new(),
                current_memory: 0,
                hits: 0,
                misses: 0,
                evictions: 0,
                expirations: 0,
                config,
            })),
            eviction_task: Mutex::new(None),
        }
    }

